package com.smartmart.analytics.service; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.order.repository.CustomerOrderRepository; import com.smartmart.product.repository.ProductRepository; import lombok.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @RequiredArgsConstructor public class AnalyticsService{private final ProductRepository products;private final InventoryRepository inventory;private final CustomerOrderRepository orders;@Transactional(readOnly=true) public Map<String,Object> dashboard(){var all=orders.findAllWithItems();Map<String,Object> r=new LinkedHashMap<>();r.put("totalProducts",products.count());r.put("totalInventoryUnits",inventory.findAll().stream().mapToInt(i->i.getQuantity()).sum());r.put("lowStockProducts",inventory.findLowStock().size());r.put("expiringInventory",inventory.findByExpiryDateBetween(LocalDate.now(),LocalDate.now().plusDays(30)).size());r.put("totalOrders",all.size());r.put("revenue",all.stream().map(o->o.getTotalAmount()).reduce(BigDecimal.ZERO,BigDecimal::add));r.put("popularProducts",all.stream().flatMap(o->o.getItems().stream()).collect(Collectors.groupingBy(i->i.getProduct().getName(),Collectors.summingInt(i->i.getQuantity()))));r.put("topCategories",all.stream().flatMap(o->o.getItems().stream()).collect(Collectors.groupingBy(i->i.getProduct().getCategory(),Collectors.summingInt(i->i.getQuantity()))));return r;}}
